import {
  Root,
  Trigger,
  Content,
  Item,
  Label,
  Separator,
  Portal,
  DropdownMenuTriggerProps,
} from "@radix-ui/react-dropdown-menu";
import styles from "./dropdown-menu.module.less";
import Icon, { Props as IconProps } from "@/core/components/primitives/icon/icon";
import { exhaustiveCheck, multipleClassNames } from "../../../helpers";
import { useModalPortal } from "@/core/components/primitives/modal-portal/modal-portal";
import {
  ButtonProps,
  PrimaryButton,
  SecondaryButton,
  GhostButton,
  OutlineButton,
} from "@/core/components/primitives/parks-button/parks-button";
import { Fragment, forwardRef, useState } from "react";
import { AnimatePresence, Variants, motion } from "framer-motion";

type MenuItem = {
  label: string;
  onClick: () => void;
  disabled?: boolean;
  rightSlot?: string | IconProps;
  testId?: string;
};

type ItemGroup = {
  label?: string;
  items: Array<MenuItem>;
};

type Props = {
  triggerButton: { buttonType: "PrimaryButton" | "SecondaryButton" | "GhostButton" | "OutlineButton" } & Omit<
    ButtonProps,
    "onClick"
  >;
  itemGroups: Array<ItemGroup>;
  contentClassName?: string;
  triggerTestId?: string;
};

const DropdownMenu = ({ triggerButton, itemGroups, contentClassName, triggerTestId }: Props) => {
  const [isOpen, setIsOpen] = useState(false);
  const modalPortal = useModalPortal();

  const totalNumberOfItems = itemGroups.reduce((acc, itemGroup) => acc + itemGroup.items.length, 0);

  const listVariants = {
    open: {
      opacity: 1,
      transition: {
        staggerChildren: totalNumberOfItems > 10 ? 0.02 : 0.05,
      },
    },
    closed: {
      opacity: 0,
    },
  } satisfies Variants;

  const itemVariants = {
    open: {
      x: 0,
      transition: {
        duration: 0.7,
        type: "spring",
      },
    },
    closed: { x: -300 },
  } satisfies Variants;

  return (
    <Root open={isOpen} onOpenChange={() => setIsOpen(!isOpen)} modal>
      <Trigger asChild>
        <TriggerButton triggerButton={triggerButton} data-testid={triggerTestId} />
      </Trigger>
      <Portal container={modalPortal}>
        <AnimatePresence>
          {isOpen && (
            <Content
              className={styles.content}
              sideOffset={5}
              onCloseAutoFocus={(e) => {
                e.preventDefault();
              }}
              asChild
            >
              <motion.div
                initial="closed"
                animate="open"
                variants={listVariants}
                className={multipleClassNames(contentClassName)}
              >
                {itemGroups.map((itemGroup, index) => (
                  <Fragment key={index}>
                    {itemGroup.label && (
                      <Label className={styles.label} asChild>
                        <motion.div variants={itemVariants}>{itemGroup.label}</motion.div>
                      </Label>
                    )}
                    {itemGroup.items.map((item, index) => (
                      <Item
                        asChild
                        key={index}
                        className={styles.item}
                        disabled={item.disabled}
                        onSelect={item.onClick}
                        data-testid={item.testId}
                      >
                        <motion.div variants={itemVariants} whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
                          <p className="body-l">{item.label}</p>
                          {item.rightSlot && (
                            <div className={styles.rightSlot}>
                              <RightSlot rightSlot={item.rightSlot} />
                            </div>
                          )}
                        </motion.div>
                      </Item>
                    ))}
                    {index < itemGroups.length - 1 && (
                      <Separator className={styles.separator} asChild>
                        <motion.div variants={itemVariants} />
                      </Separator>
                    )}
                  </Fragment>
                ))}
              </motion.div>
            </Content>
          )}
        </AnimatePresence>
      </Portal>
    </Root>
  );
};

const TriggerButton = forwardRef<HTMLButtonElement, Pick<Props, "triggerButton"> & DropdownMenuTriggerProps>(
  ({ triggerButton, ...rest }, ref) => {
    const { buttonType, ...restOfProps } = triggerButton;

    switch (buttonType) {
      case "PrimaryButton":
        return <PrimaryButton ref={ref} {...restOfProps} {...rest} />;
      case "SecondaryButton":
        return <SecondaryButton ref={ref} {...restOfProps} {...rest} />;
      case "GhostButton":
        return <GhostButton ref={ref} {...restOfProps} {...rest} />;
      case "OutlineButton":
        return <OutlineButton ref={ref} {...restOfProps} {...rest} />;
      default:
        return exhaustiveCheck(buttonType);
    }
  },
);

TriggerButton.displayName = "TriggerButton";

const RightSlot = ({ rightSlot }: Pick<MenuItem, "rightSlot">) => {
  if (typeof rightSlot === "string") {
    return <div>{rightSlot}</div>;
  }
  if (rightSlot) {
    return <Icon {...rightSlot} />;
  }
  return null;
};

export default DropdownMenu;
